// Columnas AFFILIATE_LINKS: niche, keyword, affiliate_type, anchor_text, affiliate_url, product_name, cta_text, enabled, priority, language
const posts = $('Tomar 5 a la vez').all();
const affiliateLinks = $('Read AFFILIATE_LINKS').all()
  .map(i => i.json)
  .filter(l => String(l.enabled).toUpperCase() === 'TRUE');

const results = [];

for (const postItem of posts) {
  const post = postItem.json;
  let html = post.HTML_FINAL || '';
  const niche = post.NICHO || '';
  const lang = post.IDIOMA || 'es';

  const nicheLinks = affiliateLinks.filter(l =>
    (!l.niche || l.niche === niche) && (!l.language || l.language === lang)
  );

  // 1. Reemplazar placeholders de productos
  const products = nicheLinks.filter(l => l.affiliate_type === 'product')
    .sort((a,b) => Number(a.priority||9) - Number(b.priority||9)).slice(0, 3);

  if (products[0]) {
    html = html.replace('<!-- PROD1_NAME -->', products[0].product_name || 'Producto recomendado')
               .replace('<!-- PROD1_URL -->', products[0].affiliate_url || '#')
               .replace('<!-- PROD1_CTA -->', products[0].cta_text || 'Ver en Amazon');
  }
  if (products[1]) {
    html = html.replace('<!-- PROD2_NAME -->', products[1].product_name || 'Producto recomendado')
               .replace('<!-- PROD2_URL -->', products[1].affiliate_url || '#')
               .replace('<!-- PROD2_CTA -->', products[1].cta_text || 'Ver en Amazon');
  }
  if (products[2]) {
    html = html.replace('<!-- PROD3_NAME -->', products[2].product_name || 'Producto recomendado')
               .replace('<!-- PROD3_URL -->', products[2].affiliate_url || '#')
               .replace('<!-- PROD3_CTA -->', products[2].cta_text || 'Ver en Amazon');
  }

  // 2. Reemplazar placeholder de Telegram
  const telegramLink = nicheLinks.find(l => l.affiliate_type === 'telegram');
  if (telegramLink) {
    html = html.replace(/<!--\s*TELEGRAM_URL\s*-->/g, telegramLink.affiliate_url || '#')
               .replace(/<!--\s*TELEGRAM_NAME\s*-->/g, telegramLink.product_name || 'Nuestra comunidad')
               .replace(/<!--\s*TELEGRAM_CTA\s*-->/g, telegramLink.cta_text || 'Unirte al canal');
  }

  // 3. Reemplazar placeholder de Lead Magnet
  const leadMagnet = nicheLinks.find(l => l.affiliate_type === 'lead_magnet');
  if (leadMagnet) {
    html = html.replace(/<!--\s*LEAD_MAGNET_URL\s*-->/g, leadMagnet.affiliate_url || '#')
               .replace(/<!--\s*LEAD_MAGNET_NAME\s*-->/g, leadMagnet.product_name || 'Guía gratuita')
               .replace(/<!--\s*LEAD_MAGNET_CTA\s*-->/g, leadMagnet.cta_text || 'Descargar gratis');
  }

  // 4. Inyección de keywords en texto (máx 2 links)
  const keywordLinks = nicheLinks.filter(l => l.affiliate_type === 'keyword' && l.keyword)
    .sort((a,b) => Number(a.priority||9) - Number(b.priority||9));
  let injectedCount = 0;
  for (const kl of keywordLinks) {
    if (injectedCount >= 2) break;
    const kw = kl.keyword;
    const url = kl.affiliate_url;
    const anchor = kl.anchor_text || kw;
    if (!url || !kw) continue;
    const escaped = kw.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    const pattern = new RegExp('(?<!<[^>]*)\\b(' + escaped + ')\\b(?![^<]*>)', 'i');
    if (pattern.test(html)) {
      html = html.replace(pattern, '<a href="' + url + '" rel="nofollow sponsored" target="_blank">' + anchor + '</a>');
      injectedCount++;
    }
  }

  results.push({
    json: {
      ID_UNICO: post.ID_UNICO,
      POST_ID: post.POST_ID,
      BLOG_ID: post.ID_BLOG,
      HTML_CONTENT_UPDATED: html,
      TITLE: post.TITLE
    }
  });
}

return results;
